package com.example.securexml;

import java.util.Set;
import java.util.HashSet;
import java.util.Collections;

/**
 * Enthält Konstanten für die Validierung, insbesondere eine Whitelist für erlaubte XML-Tags.
 * Dies dient der Prävention von CWE-95 (Improper Neutralization of Input During Web Page Generation).
 */
public final class XmlConstants {

    private XmlConstants() {
        // Private Constructor to prevent instantiation
    }

    /**
     * Whitelist für erlaubte Root-Element-Namen.
     * Nur diese Elemente dürfen als Wurzel eines verarbeiteten Dokuments dienen.
     */
    public static final Set<String> ALLOWED_ROOT_ELEMENTS = Collections.unmodifiableSet(
            new HashSet<>(Set.of("user", "order", "invoice"))
    );

    /**
     * Whitelist für erlaubte Kind-Element-Namen innerhalb der Root-Elemente.
     * Dies schränkt die Struktur stark ein und verhindert unbekannte Tags.
     */
    public static final Set<String> ALLOWED_CHILD_ELEMENTS = Collections.unmodifiableSet(
            new HashSet<>(Set.of("id", "name", "email", "amount", "date"))
    );

    /**
     * Maximal zulässige Tiefe der XML-Struktur, um DoS durch Rekursion zu verhindern.
     */
    public static final int MAX_DEPTH = 10;
}
