package com.example.securexml;

import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.EntityResolver;
import org.xml.sax.XMLReader;
import org.xml.sax.helpers.DefaultHandler;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.XMLConstants;
import java.io.IOException;
import java.io.StringReader;

/**
 * Sicherer XML-Parser, der XXE-Angriffe (CWE-611) verhindert.
 * Konfiguriert DocumentBuilderFactory strikt nach OWASP-Richtlinien.
 */
public class XmlParser {

    /**
     * Erstellt einen sicheren DocumentBuilderFactory.
     * Alle unsicheren Features werden explizit deaktiviert.
     */
    private DocumentBuilderFactory createSecureFactory() {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        try {
            // PRIMARY DEFENSE: Disallow DOCTYPE declarations entirely
            // Dies verhindert klassische XXE-Payloads
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // Disable external general entities
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

            // Disable external parameter entities
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

            // Disable loading external DTDs
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            // Disable XInclude
            factory.setXIncludeAware(false);

            // Enable Secure Processing Mode (Prevents Billion Laughs DoS)
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Limit entity expansion count implicitly via disallow-doctype-decl
            // Additional limit can be set via system property if supported by implementation
            System.setProperty("javax.xml.accessExternalDTD", "");
            System.setProperty("javax.xml.accessExternalSchema", "");

        } catch (ParserConfigurationException | SAXException e) {
            throw new RuntimeException("Fehler beim Initialisieren des sicheren XML-Parsers", e);
        }

        return factory;
    }

    /**
     * Parset den XML-String unter strikter Sicherheitskontrolle.
     *
     * @param xmlData Der rohe XML-Inhalt
     * @return Das geparsedte Document
     * @throws XmlValidationException Wenn die Struktur ungültig ist
     */
    public Document parse(String xmlData) throws XmlValidationException {
        if (xmlData == null || xmlData.trim().isEmpty()) {
            throw new XmlValidationException("XML-Daten dürfen nicht leer sein");
        }

        DocumentBuilderFactory factory = createSecureFactory();
        DocumentBuilder builder;
        try {
            builder = factory.newDocumentBuilder();
        } catch (ParserConfigurationException e) {
            throw new RuntimeException("Parser-Konfiguration fehlgeschlagen", e);
        }

        // Kritischer Schritt: EntityResolver setzen, um externe Aufrufe zu blockieren
        // Selbst wenn DOCTYPE erlaubt wäre, würde dies externe Ressourcen blockieren.
        builder.setEntityResolver(new NoOpEntityResolver());

        try {
            InputSource is = new InputSource(new StringReader(xmlData));
            Document doc = builder.parse(is);

            // Validierung der Struktur nach dem Parsing
            validateStructure(doc);

            return doc;
        } catch (IOException | SAXException e) {
            throw new XmlValidationException("Fehler beim Parsen der XML-Daten", e);
        }
    }

    /**
     * Prüft die XML-Struktur gegen die Whitelist (CWE-95).
     */
    private void validateStructure(Document doc) {
        Element root = doc.getDocumentElement();
        if (root == null) {
            throw new XmlValidationException("Kein Root-Element gefunden");
        }

        if (!XmlConstants.ALLOWED_ROOT_ELEMENTS.contains(root.getTagName())) {
            throw new XmlValidationException("Root-Element '" + root.getTagName() + "' ist nicht erlaubt");
        }

        checkNodeDepth(root, 0);
    }

    /**
     * Rekuriver Check der Tag-Namen und Tiefe.
     */
    private void checkNodeDepth(Element element, int depth) {
        if (depth > XmlConstants.MAX_DEPTH) {
            throw new XmlValidationException("XML-Tiefe überschreitet Maximum von " + XmlConstants.MAX_DEPTH);
        }

        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            var child = children.item(i);
            if (child instanceof Element) {
                Element childElem = (Element) child;
                if (!XmlConstants.ALLOWED_CHILD_ELEMENTS.contains(childElem.getTagName())) {
                    throw new XmlValidationException("Kind-Element '" + childElem.getTagName() + "' ist nicht erlaubt");
                }
                checkNodeDepth(childElem, depth + 1);
            }
        }
    }

    /**
     * EntityResolver, der alle externen Zugriffe blockiert.
     * Gibt immer eine leere Quelle zurück, um XXE zu verhindern.
     */
    private static class NoOpEntityResolver implements EntityResolver {
        @Override
        public InputSource resolveEntity(String publicId, String systemId) {
            // Blockiert jeglichen Zugriff auf externe Dateien oder URLs
            return new InputSource(new StringReader(""));
        }
    }
}
