package com.example.securexml;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import org.springframework.stereotype.Service;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

import java.io.StringWriter;
import java.util.HashMap;
import java.util.Map;

/**
 * Service-Schicht für die Geschäftslogik.
 * Verantwortlich für die Orchestrierung von Parsing und JSON-Konvertierung.
 */
@Service
public class XmlService {

    private final XmlParser xmlParser;
    private final ObjectMapper jsonMapper;

    public XmlService(XmlParser xmlParser) {
        this.xmlParser = xmlParser;
        // Jackson XML Mapper für sichere Konvertierung verwenden
        this.jsonMapper = new XmlMapper(); 
    }

    /**
     * Verarbeitet die XML-Daten und gibt JSON zurück.
     *
     * @param xmlData Rohes XML aus dem Request Body
     * @return JSON-String mit extrahierten Daten
     */
    public String processXml(String xmlData) {
        try {
            // 1. Sicheres Parsen (XXE Schutz)
            Document doc = xmlParser.parse(xmlData);

            // 2. Extraktion der wichtigsten Felder
            Map<String, Object> dataMap = extractData(doc);

            // 3. Konvertierung zu JSON
            return jsonMapper.writeValueAsString(dataMap);

        } catch (XmlValidationException e) {
            // Logikfehler oder Validierungsfehler
            throw e;
        } catch (Exception e) {
            // Technischer Fehler
            throw new RuntimeException("Fehler bei der XML-Verarbeitung", e);
        }
    }

    /**
     * Extrahiert Daten basierend auf der bekannten Struktur.
     * Nutzt Apache Commons Lang für String-Operationen (z.B. Trimmen).
     */
    private Map<String, Object> extractData(Document doc) {
        Map<String, Object> result = new HashMap<>();
        Element root = doc.getDocumentElement();

        if (root != null) {
            // Beispielhafte Extraktion für bekannte Tags
            NodeList idList = root.getElementsByTagName("id");
            if (idList.getLength() > 0) {
                result.put("id", idList.item(0).getTextContent().trim());
            }

            NodeList nameList = root.getElementsByTagName("name");
            if (nameList.getLength() > 0) {
                result.put("name", nameList.item(0).getTextContent().trim());
            }

            // Weitere Felder analog hinzufügen
        }

        return result;
    }
}
