package com.example.securexml;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

/**
 * REST-Controller für XML-Endpunkte.
 * Delegiert die Verarbeitung an den Service.
 */
@RestController
@RequestMapping("/api/xml")
public class XmlController {

    private final XmlService xmlService;

    public XmlController(XmlService xmlService) {
        this.xmlService = xmlService;
    }

    /**
     * POST-Endpoint zum Empfangen von XML-Daten.
     * Erwartet Text/XML im Body.
     */
    @PostMapping(consumes = "application/xml")
    public ResponseEntity<String> processXml(@RequestBody String xmlData) {
        try {
            String jsonResponse = xmlService.processXml(xmlData);
            return ResponseEntity.ok(jsonResponse);
        } catch (XmlValidationException e) {
            // 400 Bad Request für Validierungsfehler
            return ResponseEntity.badRequest().body("{\"error\": \"Validierungsfehler: " + e.getMessage() + "\"}");
        } catch (RuntimeException e) {
            // 500 Internal Server Error für technische Fehler
            return ResponseEntity.internalServerError().body("{\"error\": \"Interner Serverfehler\"}");
        }
    }
}
