package com.example.securexml;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;

/**
 * Servlet Filter, der zusätzliche Sicherheitsebenen hinzufügt.
 * Überprüft Content-Type und andere Header vor Erreichen des Controllers.
 */
@Component
public class XmlSecurityFilter extends OncePerRequestFilter {

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {

        // 1. Content-Type Überprüfung
        // Akzeptiert nur application/xml, um MIME-Sniffing Angriffe zu vermeiden
        String contentType = request.getContentType();
        if (contentType == null || !contentType.startsWith("application/xml")) {
            response.sendError(HttpServletResponse.SC_UNSUPPORTED_MEDIA_TYPE, "Nur application/xml unterstützt");
            return;
        }

        // 2. Optional: Größe des Requests begrenzen (falls Container nicht bereits tut)
        // In Production sollte dies über Nginx oder Load Balancer erfolgen

        filterChain.doFilter(request, response);
    }
}
