package com.example.securexml;

import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Spring Konfiguration für die Registrierung von Sicherheitskomponenten.
 */
@Configuration
public class SecurityConfig {

    /**
     * Registriert den XmlSecurityFilter für spezifische URL-Patterns.
     * Dies stellt sicher, dass der Filter vor dem Controller ausgeführt wird.
     */
    @Bean
    public FilterRegistrationBean<XmlSecurityFilter> xmlSecurityFilter() {
        FilterRegistrationBean<XmlSecurityFilter> registration = new FilterRegistrationBean<>();
        registration.setFilter(new XmlSecurityFilter());
        registration.addUrlPatterns("/api/xml/*");
        registration.setName("xmlSecurityFilter");
        registration.setOrder(1); // Hohe Priorität
        return registration;
    }
}
