package com.example.securexxe;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@RestController
public class CustomerController {

    private final CustomerService customerService;

    public CustomerController(CustomerService customerService) {
        this.customerService = customerService;
    }

    /**
     * Endpunkt zum Suchen von Kunden nach Namen.
     * Der Name wird sicher gefiltert, ohne ihn erneut als XML zu parsen.
     */
    @GetMapping("/api/customers")
    public ResponseEntity<List<CustomerDto>> getCustomersByName(@RequestParam String customerName) {
        // Validierung der Eingabe: Leere oder nur Whitespace-Namen ablehnen
        if (customerName == null || customerName.trim().isEmpty()) {
            throw new IllegalArgumentException("customerName darf nicht leer sein");
        }

        try {
            List<CustomerDto> customers = customerService.findCustomersByName(customerName);
            return ResponseEntity.ok(customers);
        } catch (CustomerNotFoundException e) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND).body(null);
        } catch (Exception e) {
            // In Produktion: Logging hinzufügen, keine Stacktraces zurückgeben
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(null);
        }
    }
}
