package com.example.securexxe;

import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import java.io.File;
import java.util.ArrayList;
import java.util.List;

/**
 * Zentrale Klasse zur Sicherstellung von XXE-Schutz beim Parsen von XML.
 * Kapselt alle Sicherheitsfeatures des DocumentBuilderFactory.
 */
public class SecureXmlParser {

    /**
     * Erstellt einen gehärteten DocumentBuilder.
     * Alle XXE-relevanten Features werden hier explizit gesetzt.
     *
     * @return Ein konfigurierter DocumentBuilder
     */
    public DocumentBuilder createSecureBuilder() {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        try {
            // 1. PRIMARY DEFENSE: Disallow DOCTYPE Declarations
            // Dies verhindert fast alle klassischen XXE-Angriffe.
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // 2. Disable External General Entities
            // Verhindert das Laden von externen Ressourcen über ENTITY-Declarations.
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);

            // 3. Disable External Parameter Entities
            // Verhindert Parameter-Entity-Erweiterungen.
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

            // 4. Disable Loading External DTDs
            // Verhindert das Herunterladen von DTDs von entfernten Servern.
            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            // 5. Enable Secure Processing Mode
            // Hilft bei der Verhinderung von Billion Laughs Attacken (DoS).
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // 6. Disable XInclude
            // Verhindert das Einfügen externer Dateien via XInclude.
            dbf.setXIncludeAware(false);

            // 7. Disable Entity Expansion
            // Stellt sicher, dass Entitäten nicht expandiert werden.
            dbf.setExpandEntityReferences(false);

            return dbf.newDocumentBuilder();

        } catch (Exception e) {
            // Fallback oder Logging, je nach Anforderung
            throw new RuntimeException("Fehler beim Initialisieren des sicheren XML-Parsers", e);
        }
    }

    /**
     * Lädt Kunden aus einer XML-Datei und wandelt sie in DTOs um.
     * Nutzt den oben erstellten sicheren Builder.
     */
    public List<CustomerDto> parseCustomers(File xmlFile) {
        List<CustomerDto> customers = new ArrayList<>();
        DocumentBuilder builder = createSecureBuilder();

        try {
            Document doc = builder.parse(xmlFile);
            NodeList customerNodes = doc.getElementsByTagName("customer");

            for (int i = 0; i < customerNodes.getLength(); i++) {
                Element customerElement = (Element) customerNodes.item(i);

                String id = getElementValue(customerElement, "id");
                String name = getElementValue(customerElement, "name");
                String email = getElementValue(customerElement, "email");

                customers.add(new CustomerDto(id, name, email));
            }
        } catch (Exception e) {
            throw new RuntimeException("Fehler beim Parsen der XML-Datei: " + e.getMessage(), e);
        }

        return customers;
    }

    /**
     * Validiert eine XML-Datei gegen ein XSD-Schema unter strikten Sicherheitsbedingungen.
     * Verhindert, dass das Schema selbst externe Ressourcen lädt.
     */
    public void validateSchema(File xmlFile, File xsdFile) {
        try {
            SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);

            // Kritische Sicherheitsfeature: Erlaube kein externes DTD/Schema Laden
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            Schema schema = schemaFactory.newSchema(xsdFile);

            // Validator erstellen und ebenfalls absichern
            javax.xml.validation.Validator validator = schema.newValidator();
            validator.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            validator.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            validator.validate(new javax.xml.transform.stream.StreamSource(xmlFile));

        } catch (Exception e) {
            throw new RuntimeException("Schema-Validierung fehlgeschlagen oder unsicher konfiguriert", e);
        }
    }

    private String getElementValue(Element element, String tagName) {
        NodeList nl = element.getElementsByTagName(tagName);
        if (nl.getLength() > 0) {
            return nl.item(0).getTextContent();
        }
        return "";
    }
}
