package com.example.securexxe;

import com.fasterxml.jackson.annotation.JsonProperty;

/**
 * Data Transfer Object für die JSON-Antwort.
 * Wird vom Jackson-Serializer automatisch in JSON umgewandelt.
 */
public class CustomerDto {

    @JsonProperty("id")
    private String id;

    @JsonProperty("name")
    private String name;

    @JsonProperty("email")
    private String email;

    public CustomerDto() {
    }

    public CustomerDto(String id, String name, String email) {
        this.id = id;
        this.name = name;
        this.email = email;
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }
}
